 33	/// Represents a template that is utilized to generate command strings.
 34	///
 35	/// The template is meant to be coupled with an input in order to generate a command. The
 36	/// `generate_and_execute()` method will be used to generate a command and execute it.
 37	#[derive(Debug, Clone, PartialEq)]
 38	pub struct CommandTemplate {
 39	    args: Vec<ArgumentTemplate>,
 40	    mode: ExecutionMode,
 41	    path_separator: Option<String>,
 42	}
 43	
 44	impl CommandTemplate {
 45	    pub fn new<I, S>(input: I, path_separator: Option<String>) -> CommandTemplate
 46	    where
 47	        I: IntoIterator<Item = S>,
 48	        S: AsRef<str>,
 49	    {
 50	        Self::build(input, ExecutionMode::OneByOne, path_separator)
 51	    }
 52	
 53	    pub fn new_batch<I, S>(input: I, path_separator: Option<String>) -> Result<CommandTemplate>
 54	    where
 55	        I: IntoIterator<Item = S>,
 56	        S: AsRef<str>,
 57	    {
 58	        let cmd = Self::build(input, ExecutionMode::Batch, path_separator);
 59	        if cmd.number_of_tokens() > 1 {
 60	            return Err(anyhow!("Only one placeholder allowed for batch commands"));
 61	        }
 62	        if cmd.args[0].has_tokens() {
 63	            return Err(anyhow!(
 64	                "First argument of exec-batch is expected to be a fixed executable"
 65	            ));
 66	        }
 67	        Ok(cmd)
 68	    }
 69	
 70	    fn build<I, S>(input: I, mode: ExecutionMode, path_separator: Option<String>) -> CommandTemplate
 71	    where
 72	        I: IntoIterator<Item = S>,
 73	        S: AsRef<str>,
 74	    {
 75	        lazy_static! {
 76	            static ref PLACEHOLDER_PATTERN: Regex = Regex::new(r"\{(/?\.?|//)\}").unwrap();
 77	        }
 78	
 79	        let mut args = Vec::new();
 80	        let mut has_placeholder = false;
 81	
 82	        for arg in input {
 83	            let arg = arg.as_ref();
 84	
 85	            let mut tokens = Vec::new();
 86	            let mut start = 0;
 87	
 88	            for placeholder in PLACEHOLDER_PATTERN.find_iter(arg) {
 89	                // Leading text before the placeholder.
 90	                if placeholder.start() > start {
 91	                    tokens.push(Token::Text(arg[start..placeholder.start()].to_owned()));
 92	                }
 93	
 94	                start = placeholder.end();
 95	
 96	                match placeholder.as_str() {
 97	                    "{}" => tokens.push(Token::Placeholder),
 98	                    "{.}" => tokens.push(Token::NoExt),
 99	                    "{/}" => tokens.push(Token::Basename),
100	                    "{//}" => tokens.push(Token::Parent),
101	                    "{/.}" => tokens.push(Token::BasenameNoExt),
102	                    _ => unreachable!("Unhandled placeholder"),
103	                }
104	
105	                has_placeholder = true;
106	            }
107	
108	            // Without a placeholder, the argument is just fixed text.
109	            if tokens.is_empty() {
110	                args.push(ArgumentTemplate::Text(arg.to_owned()));
111	                continue;
112	            }
113	
114	            if start < arg.len() {
115	                // Trailing text after last placeholder.
116	                tokens.push(Token::Text(arg[start..].to_owned()));
117	            }
118	
119	            args.push(ArgumentTemplate::Tokens(tokens));
120	        }
121	
122	        // If a placeholder token was not supplied, append one at the end of the command.
123	        if !has_placeholder {
124	            args.push(ArgumentTemplate::Tokens(vec![Token::Placeholder]));
125	        }
126	
127	        CommandTemplate {
128	            args,
129	            mode,
130	            path_separator,
131	        }
132	    }
