138	    /// Generates and executes a command.
139	    ///
140	    /// Using the internal `args` field, and a supplied `input` variable, a `Command` will be
141	    /// build. Once all arguments have been processed, the command is executed.
142	    pub fn generate_and_execute(
143	        &self,
144	        input: &Path,
145	        out_perm: Arc<Mutex<()>>,
146	        buffer_output: bool,
147	    ) -> ExitCode {
148	        let input = strip_current_dir(input);
149	
150	        let mut cmd = Command::new(self.args[0].generate(&input, self.path_separator.as_deref()));
151	        for arg in &self.args[1..] {
152	            cmd.arg(arg.generate(&input, self.path_separator.as_deref()));
153	        }
154	
155	        execute_command(cmd, &out_perm, buffer_output)
156	    }
