+        let mut cmd = Command::new(executable);
+        cmd.stdin(Stdio::inherit());
+        cmd.stdout(Stdio::inherit());
+        cmd.stderr(Stdio::inherit());
+
+        for index in 1..self.args.len() {
+            if index == path_arg_position {
+                for path in paths {
+                    cmd.arg(path);
+                }
+            } else if let Some((_, arg)) = fixed_args.iter().find(|(arg_index, _)| *arg_index == index) {
+                cmd.arg(arg);
+            }
+        }
+
+        execute_command(cmd, &Mutex::new(()), buffer_output)
+    }
+}
